validity_rows = []
for j in range(len(d)):
    issues = []
    if not qkeep[j]: issues.append('quality_rule')
    if not time_ok[j]: issues.append('nonfinite_time')
    if not flux_ok[j]: issues.append('nonfinite_flux')
    if not error_ok[j]: issues.append('nonfinite_error')
    if error_ok[j] and not error_positive[j]: issues.append('nonpositive_error')
    if not qkeep[j]:
        final_group = 'quality_rejected'
    elif not finite[j]:
        final_group = 'additional_invalid'
    else:
        final_group = 'accepted'
    validity_rows.append([j, int(d['CADENCENO'][j]), float(d['TIME'][j]),
        float(d['PDCSAP_FLUX'][j]), float(d['PDCSAP_FLUX_ERR'][j]), int(q[j]),
        bool(time_ok[j]), bool(flux_ok[j]), bool(error_ok[j]), bool(error_positive[j]),
        bool(qkeep[j]), bool(finite[j]), bool(keep[j]), final_group, ';'.join(issues)])
validity_header = ['raw_row', 'cadenceno', 'time_bkjd', 'pdcsap_flux', 'pdcsap_flux_err', 'quality',
    'time_finite', 'flux_finite', 'error_finite', 'error_positive', 'quality_keep', 'finite_keep',
    'retained', 'final_group', 'all_failure_reasons']
save_csv('validity-ledger.csv', validity_header, validity_rows)
mask_rows = [[j, int(d['CADENCENO'][j]), bool(keep[j])] for j in range(len(d))]
save_csv('keep-mask.csv', ['raw_row', 'cadenceno', 'keep'], mask_rows)

candidate_path = ROOT / 'student-input/candidate-window.json'
candidate_pending = []
candidate = {}
if not candidate_path.is_file():
    candidate_pending.append(f'缺少位置卡：{candidate_path}')
else:
    try:
        candidate = json.loads(candidate_path.read_text(encoding='utf-8'))
    except (OSError, ValueError) as exc:
        candidate_pending.append(f'位置卡无法读取：{exc}')
if not isinstance(candidate, dict):
    candidate_pending.append('位置卡应是一条有字段名的 JSON 记录。')
    candidate = {}
start = candidate.get('start_bkjd')
end = candidate.get('end_bkjd')
numbers_ok = (isinstance(start, (int, float)) and not isinstance(start, bool)
              and isinstance(end, (int, float)) and not isinstance(end, bool)
              and np.isfinite(start) and np.isfinite(end))
if not numbers_ok or (numbers_ok and start >= end):
    candidate_pending.append('请填写真实起止时间：有限数字，且 start_bkjd < end_bkjd。')
if candidate.get('boundary') != '[start,end)':
    candidate_pending.append('请把边界写为 [start,end)，并按这个规则核对编号。')
chosen_cadence = candidate.get('cadenceno', [])
if not isinstance(chosen_cadence, list) or len(chosen_cadence) < 2:
    candidate_pending.append('请保留至少两个从原表查到的采样编号。')
elif numbers_ok and start < end:
    for wanted in chosen_cadence:
        if not isinstance(wanted, int) or isinstance(wanted, bool):
            candidate_pending.append('cadenceno 中每项应为真实整数编号。'); break
        found = np.flatnonzero(d['CADENCENO'] == wanted)
        if len(found) != 1 or not (start <= float(d['TIME'][found[0]]) < end):
            candidate_pending.append(f'编号 {wanted} 不在所写 Q3 区间，回原表核对。')
if not isinstance(candidate.get('observation'), str) or not candidate.get('observation', '').strip():
    candidate_pending.append('请填写实际观察；暂时看不清下降也可如实写。')
if candidate_pending:
    print('窗口对照待完成：')
    for message in candidate_pending: print('-', message)
    save_json('deletion-task-status.json', {'status': 'pending', 'reasons': candidate_pending,
        'global_trial_executed': True, 'production_uses_low_flux_deletion': False})
else:
    window_mask = (lc.time.value >= start) & (lc.time.value < end)
    window_removed = window_mask & trial_remove
    window_after = window_mask & ~trial_remove
    n_before = int(window_mask.sum()); n_removed = int(window_removed.sum()); n_after = int(window_after.sum())
    if n_before == 0:
        comparison_note = '所选窗口没有已接受记录，无法比较，不是测得没有下降。'
    elif n_after == 0:
        comparison_note = '试验后窗内无记录，无法由剩余观测估计其变化。'
    elif n_removed == 0:
        comparison_note = '本窗没有记录被此门槛标记，不能据此判断行星是否存在。'
    else:
        comparison_note = '记录减少；是否为信号仍需质量、重复性与来源检查。'
    print('本窗原有 / 试验删除 / 试验后', n_before, n_removed, n_after)
    print(comparison_note)
    save_csv('deletion-comparison.csv', ['start_bkjd', 'end_bkjd', 'boundary', 'threshold',
        'before', 'removed', 'after', 'note'], [[start, end, '[start,end)', threshold, n_before, n_removed, n_after, comparison_note]])
    fig, axes = plt.subplots(1, 2, figsize=(12, 4), sharex=True, sharey=True)
    axes[0].scatter(lc.time.value[window_mask], lc.flux.value[window_mask], s=18)
    axes[0].scatter(lc.time.value[window_removed], lc.flux.value[window_removed], s=45, facecolors='none', edgecolors='orange')
    axes[1].scatter(lc.time.value[window_after], lc.flux.value[window_after], s=18)
    axes[0].set_title('Before; circles mark trial removals'); axes[1].set_title('Trial subset only')
    for ax in axes:
        ax.set_xlim(start, end); ax.set_xlabel('BKJD (TDB) [day]')
    axes[0].set_ylabel('Relative flux')
    if n_before == 0:
        for ax in axes: ax.text(0.5, 0.5, 'No accepted observations', transform=ax.transAxes, ha='center')
    save_plot('deletion-comparison.png')
    save_json('deletion-task-status.json', {'status': 'compared', 'candidate_input': str(candidate_path),
        'start_bkjd': start, 'end_bkjd': end, 'note': comparison_note, 'production_uses_low_flux_deletion': False})
assert np.array_equal(np.asarray(lc.cadenceno), before_trial_cadence)
assert np.array_equal(lc.flux.value, before_trial_flux)
assert int(keep.sum()) == 4134
print('正式 lc 与 keep 未被试验覆盖。')
